mapper.select:
select ,
       1 - (v.vector <=> cast(#{vector} as vector)) as vector_score
from ${table} v
join ai_knowledge_chunk c on c.id = v.chunk_id and c.document_id = v.document_id

where 
  and v.knowledge_base_id = b.id
  and v.model_connection_id = #{connectionId}
  and v.index_version = #{indexVersion}
  and v.processing_version = d.processing_version

    and 1 - (v.vector <=> cast(#{vector} as vector)) >= #{threshold}

order by v.vector <=> cast(#{vector} as vector)
limit #{size}

select from ai_knowledge_chunk c
where and c.id in
#{id}
